impl From<u16> for Bash {
    #[inline]
    fn from(x: u16) -> Self {
        num_traits::FromPrimitive::from_u16(x).unwrap_or(Self::Error)
    }
}

// Bash == u16
impl PartialEq<u16> for Bash {
    #[inline]
    fn eq(&self, x: &u16) -> bool {
        *self == Into::<Self>::into(*x)
    }
}

// u16 == Bash
impl PartialEq<Bash> for u16 {
    #[inline]
    fn eq(&self, x: &Bash) -> bool {
        *x == *self
    }
}
